#!/usr/bin/env ruby
# typed: true
# frozen_string_literal: true

# generate-routing-schema.rb
#
# This script is the entrypoint for generating routing details for consumption by the API Gateway agent.
#
# it consumes the `programmatic_access.yaml` file, which contains access entries for various routes,
# and the gateway-route-rate-limit-date.yaml file which is generated by script/generate-routing-schema-rate-limit-data.rb
# to generate both files call `script/generate-routing-schema-full.rb`


require "json-schema"
require "sorbet-runtime"
require "yaml"
require_relative "route_generator"

GATEWAY_ROUTE_SCHEMA = {
  "type" => "object",
   "additionalProperties" => {
      "type" => "array",
      "properties" => {
        "type" => "array",
        "items" => {
          "type" => "object",
          "additionalProperties" => false,
          "required" => %w[method operation_ids catalog_service allow_unauthenticated_access backend_route],
          "properties" => {
            "method" => {
              "type" => "string",
              "enum" => %w[GET POST PUT PATCH DELETE HEAD OPTIONS],
            },
            "operation_ids" => {
              "type" => "string",
            },
            "catalog_service" => {
              "type" => "string",
            },
            "allow_unauthenticated_access" => {
              "type" => "boolean",
            },
            "backend_route" => {
              "type" => "string",
            },
            "skip_primary_rate_limit" => {
              "type" => "boolean",
            },
            "primary_rate_limit_family" => {
              "type" => "string",
            },
          }
        }
      }
   }
}

def validate_route_schema_definition!(hash)
  JSON::Validator.validate!(GATEWAY_ROUTE_SCHEMA, hash)
end

def determine_rate_limits(http_method, internal_route, external_routes, operation_ids, namespace, rate_limit_data)
  # First try to match using the internal route with placeholders
  internal_route_with_placeholders = RouteGenerator.convert_placeholders_to_external_representation(internal_route)

  # Check if this specific internal route + method has rate limit data
  if rate_limit_data.key?(internal_route_with_placeholders) &&
     rate_limit_data[internal_route_with_placeholders].key?(http_method)

    route_data = T.let(nil, T.nilable(T::Hash[String, T.untyped]))
    route_data = rate_limit_data[internal_route_with_placeholders][http_method]
    return [
      route_data["skip_primary_rate_limit"],
      route_data["primary_rate_limit_family"]
    ]
  end

  # If not found with internal route, try each external route
  external_routes.each do |route|
    if rate_limit_data.key?(route) && rate_limit_data[route].key?(http_method)
      route_data = rate_limit_data[route][http_method]
      return [
        route_data["skip_primary_rate_limit"],
        route_data["primary_rate_limit_family"]
      ]
    end
  end

  # If no match found in the data file, warn and return default values.
  # we don't want to raise here, because we want the file to be fully generated for CI
  # In CI this will cause the check to fail, because the diff will be non-empty
  puts "Warning: No rate limit data found for #{http_method} #{internal_route} with operation_ids: #{operation_ids} in namespace: #{namespace}."
  puts "Please run `script/generate-routing-schema-rate-limit-data.rb` to update the rate limit data file."
  puts "Using default values: skip_primary_rate_limit=false, primary_rate_limit_family='missing'."

  # Default values if no match is found
  [false, "missing"]
end

def resolve_routes_for_schema(access_entry, rate_limit_data)
  operation_ids = access_entry["operation_ids"]
  service = access_entry["service"]
  allows_public_read = RouteGenerator.parse_bool(access_entry["allows_public_read"], false)
  namespace = access_entry["namespace"]

  endpoint = access_entry["endpoint"]

  if RouteGenerator::IGNORED_GHES_ROUTES.include?(endpoint)
    # escape hatch to ignore some routes that are legacy GHES only and not worth bringing along
    return nil
  end

  http_method, internal_route = endpoint.split(" ")
  if http_method.nil?
    raise Exception, "unable to parse method from endpoint: #{endpoint}"
  end
  if internal_route.nil?
    raise Exception, "unable to parse endpoint from endpoint: #{endpoint}"
  end

  # these routes are publicly accessible despite not defining `allows_public_read`
  # in programmatic_access.yaml
  if ["/_private/browser/stats", "/_private/browser/errors"].include?(internal_route)
    allows_public_read = true
  end

  backend_route = if RouteGenerator.regex_route?(internal_route)
    regex_route = Regexp.new(internal_route)
    # inspect is a better represention for our case, because to_s embeds additional details to be able to recreate the regex
    regex_str = regex_route.inspect
    # trim first and last character from regex string representation
    regex_str[1..-2]
  else
    internal_route
  end

  external_routes = RouteGenerator.resolve_external_routes(internal_route, operation_ids)
  if external_routes.empty?
    return nil
  end

  skip_primary_rate_limit, primary_rate_limit_family = determine_rate_limits(http_method, internal_route, external_routes, operation_ids, namespace, rate_limit_data)

  route_metadata = RouteGenerator::RouteMetadata.new(
    backend_route: backend_route,
    operation_ids: operation_ids,
    http_method: http_method,
    catalog_service: "github/#{service}",
    allow_unauthenticated_access: allows_public_read,
    skip_primary_rate_limit: skip_primary_rate_limit,
    primary_rate_limit_family: primary_rate_limit_family
  )

  routes = []

  external_routes.each do |external_route|
    internal_route_with_placeholders = RouteGenerator.convert_placeholders_to_external_representation(internal_route)
    if internal_route_with_placeholders.nil?
      routes << external_route
    else
      if internal_route_with_placeholders.end_with?("{repo}/?*", "contents(/*)?")
        raise Exception, "unable to parse route: #{internal_route_with_placeholders} - this should not be hit!"
      end

      if RouteGenerator.regex_route?(internal_route_with_placeholders)
        # internal routes that look like regexes are not supported in the schema, only use the external representation
        routes << external_route
      elsif internal_route_with_placeholders != external_route
        routes << external_route
        routes << internal_route_with_placeholders
      else
        routes << external_route
      end
    end
  end

  RouteGenerator::RouteDefinition.new(
    routes: routes.uniq,
    metadata: route_metadata,
  )
end

if $PROGRAM_NAME == __FILE__
  # Enabling YJIT speeds up cache generation by about 25%
  RubyVM::YJIT.enable if defined?(RubyVM::YJIT) && RubyVM::YJIT.respond_to?(:enable)

  puts "Running script"
  access_entries = RouteGenerator.load_access_entries
  puts "Loaded #{access_entries.size} access entries"

  puts "Loading rate limit data"
  # Path to the rate limit data file
  root_directory = File.expand_path("..", __dir__)
  rate_limit_file = File.join(root_directory, "app/api/gateway-routes-primary-rate-limits.yaml")
  # Check if the rate limit file exists, if not return default values
  unless File.exist?(rate_limit_file)
    raise "Error: Rate limit data file not found at #{rate_limit_file}"
  end

  # Load the rate limit data
  puts "Opening rate limit data from #{rate_limit_file}"
  rate_limit_contents = File.open(rate_limit_file, "r")
  puts "Reading rate limit data..."
  rate_limit_data = YAML.safe_load(rate_limit_contents)
  puts "Loaded #{rate_limit_data.size} rate_limit entries"

  lookup_by_route = T.let({}, T::Hash[String, T::Array[T::Hash[String, T.untyped]]])

  puts "Processing routes..."
  access_entries.each do |access_entry|
    result = resolve_routes_for_schema(access_entry, rate_limit_data)
    if result.nil?
      next
    end

    metadata = result.metadata

    result.routes.each do |route|
      route_contents = {
        "method" => metadata.http_method,
        "operation_ids" => metadata.operation_ids,
        "catalog_service" => metadata.catalog_service,
        "allow_unauthenticated_access" => metadata.allow_unauthenticated_access,
        "backend_route" => metadata.backend_route,
        "skip_primary_rate_limit" => metadata.skip_primary_rate_limit,
        "primary_rate_limit_family" => metadata.primary_rate_limit_family,
      }

      if lookup_by_route.has_key?(route)
        # append new hash to existing route
        current_value = T.must(lookup_by_route[route])
        current_value << route_contents

        lookup_by_route[route] = current_value
      else
        # create new entry for route using first hash for body
        lookup_by_route[route] = [route_contents]
      end
    end
  end

  puts "Adding HEAD and OPTIONS routes..."
  # Add HEAD routes for all GET routes if they don't already exist
  # This is because Sinatra automatically registers HEAD routes for GET routes,
  # and the gateway should route these appropriately.
  routes_to_add = {}
  lookup_by_route.each do |route_path, route_configs|
    get_config = route_configs.find { |config| config["method"] == "GET" }
    head_exists = route_configs.any? { |config| config["method"] == "HEAD" }
    options_exists = route_configs.any? { |config| config["method"] == "OPTIONS" }

    # If there's a GET route but no HEAD route, create a HEAD route with the same config
    if get_config && !head_exists
      # Create a deep copy of the GET config and change the method to HEAD
      head_config = get_config.transform_values { |v| v.is_a?(Hash) ? v.dup : v }
      head_config = head_config.dup
      head_config["method"] = "HEAD"

      # Add to the routes that need to be added
      routes_to_add[route_path] ||= []
      routes_to_add[route_path] << head_config
    end

    unless options_exists
      first_config = T.must(route_configs.first)
      # Create a deep copy of the first config and change the method to OPTIONS
      options_config = first_config.transform_values { |v| v.is_a?(Hash) ? v.dup : v }
      options_config = options_config.dup
      options_config["method"] = "OPTIONS"
      options_config["allow_unauthenticated_access"] = true

      # Add to the routes that need to be added
      routes_to_add[route_path] ||= []
      routes_to_add[route_path] << options_config
    end
  end

  # Add the new HEAD routes to the lookup
  routes_to_add.each do |route_path, configs|
    lookup_by_route[route_path] ||= []
    T.must(lookup_by_route[route_path]).concat(configs)
  end

  puts "Sorting routes..."
  sorted_routes = Hash[lookup_by_route.sort_by { |key, _| key }]

  sorted_routes.each do |_, entries|
    entries.sort_by! { |entry| entry["method"] }
  end

  puts "Validating schema..."
  validate_route_schema_definition!(sorted_routes)

  root_directory = File.expand_path("..", __dir__)
  output = File.join(root_directory, "app/api/gateway-routes.yaml")

  YAML.dump(sorted_routes, File.open(output, "w"))
  puts "Done!"
end
